import fs from 'node:fs';

const target = process.argv[2];
if (!target) throw new Error('Usage: node scripts/preview-offer-57-60off-from-production-v2.mjs <html-file>');

let html = fs.readFileSync(target, 'utf8');

// Normalize every visible offer reference generated by the production build.
html = html.split('50%').join('60%');
html = html.split('cinquenta por cento').join('sessenta por cento');
html = html.split('Cinquenta por cento').join('Sessenta por cento');
html = html.split('12x de R$6,93').join('12x de R$5,90');
html = html.split('12x de R$ 6,93').join('12x de R$ 5,90');
html = html.split('R$67').join('R$57');
html = html.split('R$ 67').join('R$ 57');
html = html.replace(
  /(<div class="sm-offer-value-final"><sup>R\$<\/sup><strong>)67(<\/strong><span>,00<\/span><\/div>)/g,
  '$157$2'
);

const heroUrgency = `
<div class="sm-daily-urgency sm-daily-urgency--hero" role="note" aria-label="Prazo da oferta de hoje">
  <span class="sm-daily-urgency-kicker">OFERTA DE HOJE · 60% OFF</span>
  <span class="sm-daily-urgency-copy">Termina hoje, <strong data-sm-offer-date>--</strong></span>
  <span class="sm-daily-urgency-clock" data-sm-countdown>--:--:--</span>
</div>`;

if (!html.includes('sm-daily-urgency--hero')) {
  const desktopNeedle = '<div class="sm-dh-copy">';
  const mobileNeedle = '<div class="sm-mh-copy">';
  if (!html.includes(desktopNeedle) || !html.includes(mobileNeedle)) {
    throw new Error('Hero containers not found.');
  }
  html = html.replace(desktopNeedle, desktopNeedle + heroUrgency);
  html = html.replace(mobileNeedle, mobileNeedle + heroUrgency);
}

const checkoutUrgency = `
<div class="sm-daily-urgency sm-daily-urgency--checkout" role="note" aria-label="Prazo da oferta de hoje">
  <span>O valor promocional termina <strong>hoje, <b data-sm-offer-date>--</b></strong></span>
  <div class="sm-daily-countdown" aria-label="Contagem regressiva até meia-noite">
    <div><strong data-sm-countdown-hours>--</strong><small>HORAS</small></div><i>:</i>
    <div><strong data-sm-countdown-minutes>--</strong><small>MIN</small></div><i>:</i>
    <div><strong data-sm-countdown-seconds>--</strong><small>SEG</small></div>
  </div>
</div>`;

if (!html.includes('sm-daily-urgency--checkout')) {
  const kicker = '<span class="sm-offer-value-checkout-kicker">HOJE, COM A OFERTA ATUAL</span>';
  if (!html.includes(kicker)) throw new Error('Offer checkout kicker not found.');
  html = html.replace(kicker, kicker + checkoutUrgency);
}

const css = `<style id="sm-preview-offer-57-60off-from-production-v2">
.sm-daily-urgency--hero{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;width:min(100%,620px);margin:0 0 14px;padding:9px 11px;border:1px solid rgba(239,100,31,.24);border-radius:14px;background:linear-gradient(135deg,#fff9f4,#fff4ec);box-shadow:0 8px 22px rgba(96,55,30,.07);color:#433b49}
.sm-daily-urgency-kicker{display:inline-flex;align-items:center;min-height:28px;padding:0 9px;border-radius:999px;background:#ef641f;color:#fff;font-size:10px;font-weight:950;letter-spacing:.08em;white-space:nowrap}
.sm-daily-urgency-copy{font-size:11px;font-weight:750;color:#625969}.sm-daily-urgency-copy strong{color:#2f2836}
.sm-daily-urgency-clock{font-variant-numeric:tabular-nums;color:#e45d1c;font-size:14px;font-weight:950;letter-spacing:.035em;white-space:nowrap}
.sm-daily-urgency--checkout{position:relative;z-index:1;margin:14px 0 2px;padding:14px;border:1px solid rgba(255,255,255,.16);border-radius:16px;background:rgba(255,255,255,.08)}
.sm-daily-urgency--checkout>span{display:block;margin-bottom:10px;color:#f4effa;font-size:12px;line-height:1.35}.sm-daily-urgency--checkout>span strong{color:#fff}.sm-daily-urgency--checkout>span b{font:inherit;color:#ffd6bf}
.sm-daily-countdown{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;align-items:center;gap:7px}.sm-daily-countdown>div{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:58px;padding:7px 5px;border-radius:12px;background:#fff;color:#34293e;box-shadow:0 8px 22px rgba(20,12,31,.14)}
.sm-daily-countdown>div strong{font-variant-numeric:tabular-nums;font-size:23px;line-height:1;font-weight:950}.sm-daily-countdown>div small{margin-top:5px;color:#817789;font-size:7px;font-weight:900;letter-spacing:.11em}.sm-daily-countdown>i{color:#e5d9ee;font-style:normal;font-size:20px;font-weight:900}
.sm-sales-dock .sm-dock-daily{display:none}
@media(max-width:720px){.sm-daily-urgency--hero{grid-template-columns:1fr auto;gap:6px 10px;width:100%;margin:0 0 15px;padding:10px 11px}.sm-daily-urgency-kicker{grid-column:1/2;width:max-content}.sm-daily-urgency-copy{grid-column:1/2;font-size:10.5px}.sm-daily-urgency-clock{grid-column:2/3;grid-row:1/3;align-self:center;font-size:15px}.sm-daily-urgency--checkout{margin-top:13px;padding:13px}.sm-daily-countdown>div{min-height:54px}.sm-daily-countdown>div strong{font-size:22px}.sm-sales-dock .sm-dock-daily{display:inline-flex;align-items:center;gap:5px;flex:0 0 auto;margin-left:auto;color:#5b5262;font-size:9px;font-weight:850;white-space:nowrap}.sm-sales-dock .sm-dock-daily strong{color:#ef641f;font-variant-numeric:tabular-nums;font-size:11px;font-weight:950}.sm-sales-dock .sm-dock-actions{margin-left:6px!important}}
@media(max-width:390px){.sm-sales-dock .sm-dock-daily span{display:none}.sm-sales-dock .sm-dock-daily strong{font-size:10px}.sm-sales-dock{gap:7px!important}.sm-daily-urgency-clock{font-size:14px}}
</style>`;
html = html.replace('</head>', css + '\n</head>');

const runtime = `<script id="sm-preview-offer-57-60off-from-production-v2-runtime">
(function(){
  var OFFSET_MS=3*60*60*1000;
  var dateFmt=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Fortaleza',day:'numeric',month:'long'});
  function pad(n){return String(n).padStart(2,'0');}
  function remaining(nowMs){
    var localMs=nowMs-OFFSET_MS;
    var d=new Date(localMs);
    var nextLocalMidnight=Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()+1,0,0,0);
    var nextUtc=nextLocalMidnight+OFFSET_MS;
    return Math.max(0,Math.floor((nextUtc-nowMs)/1000));
  }
  function ensureDock(){
    var dock=document.querySelector('.sm-sales-dock');
    if(!dock||dock.querySelector('.sm-dock-daily'))return;
    var el=document.createElement('div');
    el.className='sm-dock-daily';
    el.innerHTML='<span>HOJE</span><strong data-sm-countdown>--:--:--</strong>';
    var actions=dock.querySelector('.sm-dock-actions');
    dock.insertBefore(el,actions||null);
  }
  function tick(){
    ensureDock();
    var now=new Date();
    var label=dateFmt.format(now);
    document.querySelectorAll('[data-sm-offer-date]').forEach(function(el){el.textContent=label;});
    var left=remaining(now.getTime());
    var h=Math.floor(left/3600),m=Math.floor((left%3600)/60),s=left%60;
    var clock=pad(h)+':'+pad(m)+':'+pad(s);
    document.querySelectorAll('[data-sm-countdown]').forEach(function(el){el.textContent=clock;});
    document.querySelectorAll('[data-sm-countdown-hours]').forEach(function(el){el.textContent=pad(h);});
    document.querySelectorAll('[data-sm-countdown-minutes]').forEach(function(el){el.textContent=pad(m);});
    document.querySelectorAll('[data-sm-countdown-seconds]').forEach(function(el){el.textContent=pad(s);});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',tick,{once:true});else tick();
  setInterval(tick,500);
})();
</script>`;
html = html.replace('</body>', runtime + '\n</body>');

fs.writeFileSync(target, html);
console.log('Preview applied from production base: R$57, 60% OFF, 12x R$5,90, daily countdown.');
